import java.util.*;

public class Main {
    public static void main(String[] args) {
        JobScheduler scheduler = new JobScheduler();

        // Two scheduler nodes race for the same trigger; only one should win.
        System.out.println(scheduler.tryClaimAndExecute("node-1", "daily-report", 1000));
        System.out.println(scheduler.tryClaimAndExecute("node-2", "daily-report", 1000));
        // A different trigger time for the same job has no conflict at all.
        System.out.println(scheduler.tryClaimAndExecute("node-2", "daily-report", 2000));

        // The scheduler recovers after downtime; hourly-sync's schedule shows triggers
        // at 100, 200, 300, 400 with 200 and 300 missed while it was down, 400 not yet due.
        List<Long> missed = Arrays.asList(200L, 300L);
        System.out.println("ALL policy executes: " + scheduler.resolveCatchUp(missed, "ALL"));
        System.out.println("COALESCE policy executes: " + scheduler.resolveCatchUp(missed, "COALESCE"));
        System.out.println("SKIP policy executes: " + scheduler.resolveCatchUp(missed, "SKIP"));

        // A job with no missed triggers at all, coalescing an empty set stays empty.
        List<Long> none = new ArrayList<>();
        System.out.println("COALESCE policy with no missed triggers executes: " + scheduler.resolveCatchUp(none, "COALESCE"));
    }
}

// A distributed job scheduler: a trigger lock guarantees exactly one node
// executes any single job trigger, and each job's own configured catch-up
// policy deliberately decides what happens to triggers missed during downtime.
class JobScheduler {
    private final Set<String> claimedTriggers = new HashSet<>();

    String tryClaimAndExecute(String nodeId, String jobId, long triggerTime) {
        String key = jobId + "@" + triggerTime;
        if (claimedTriggers.contains(key)) {
            return nodeId + ": LOST race for " + jobId + " at trigger " + triggerTime + ", already claimed";
        }
        claimedTriggers.add(key);
        return nodeId + ": WON race, executing " + jobId + " for trigger " + triggerTime;
    }

    List<Long> resolveCatchUp(List<Long> missedTriggerTimes, String policy) {
        switch (policy) {
            case "ALL":
                return new ArrayList<>(missedTriggerTimes);
            case "COALESCE":
                if (missedTriggerTimes.isEmpty()) return new ArrayList<>();
                return new ArrayList<>(Collections.singletonList(missedTriggerTimes.get(missedTriggerTimes.size() - 1)));
            case "SKIP":
                return new ArrayList<>();
            default:
                throw new IllegalArgumentException("unknown policy: " + policy);
        }
    }
}

