class JobScheduler:
    # A distributed job scheduler: a trigger lock guarantees exactly one node
    # executes any single job trigger, and each job's own configured catch-up
    # policy deliberately decides what happens to triggers missed during downtime.
    def __init__(self):
        self.claimed_triggers = set()

    def try_claim_and_execute(self, node_id, job_id, trigger_time):
        key = f"{job_id}@{trigger_time}"
        if key in self.claimed_triggers:
            return f"{node_id}: LOST race for {job_id} at trigger {trigger_time}, already claimed"
        self.claimed_triggers.add(key)
        return f"{node_id}: WON race, executing {job_id} for trigger {trigger_time}"

    def resolve_catch_up(self, missed_trigger_times, policy):
        if policy == "ALL":
            return list(missed_trigger_times)
        elif policy == "COALESCE":
            if not missed_trigger_times:
                return []
            return [missed_trigger_times[-1]]
        elif policy == "SKIP":
            return []
        else:
            raise ValueError(f"unknown policy: {policy}")


def main():
    scheduler = JobScheduler()

    # Two scheduler nodes race for the same trigger; only one should win.
    print(scheduler.try_claim_and_execute("node-1", "daily-report", 1000))
    print(scheduler.try_claim_and_execute("node-2", "daily-report", 1000))
    # A different trigger time for the same job has no conflict at all.
    print(scheduler.try_claim_and_execute("node-2", "daily-report", 2000))

    # The scheduler recovers after downtime; hourly-sync's schedule shows triggers
    # at 100, 200, 300, 400 with 200 and 300 missed while it was down, 400 not yet due.
    missed = [200, 300]
    print("ALL policy executes:", scheduler.resolve_catch_up(missed, "ALL"))
    print("COALESCE policy executes:", scheduler.resolve_catch_up(missed, "COALESCE"))
    print("SKIP policy executes:", scheduler.resolve_catch_up(missed, "SKIP"))

    # A job with no missed triggers at all, coalescing an empty set stays empty.
    none = []
    print("COALESCE policy with no missed triggers executes:", scheduler.resolve_catch_up(none, "COALESCE"))


if __name__ == "__main__":
    main()

