#include <iostream>
#include <string>
#include <vector>
#include <set>
#include <stdexcept>
using namespace std;

// A distributed job scheduler: a trigger lock guarantees exactly one node
// executes any single job trigger, and each job's own configured catch-up
// policy deliberately decides what happens to triggers missed during downtime.
class JobScheduler {
public:
    string tryClaimAndExecute(const string& nodeId, const string& jobId, long long triggerTime) {
        string key = jobId + "@" + to_string(triggerTime);
        if (claimedTriggers.count(key)) {
            return nodeId + ": LOST race for " + jobId + " at trigger " + to_string(triggerTime) + ", already claimed";
        }
        claimedTriggers.insert(key);
        return nodeId + ": WON race, executing " + jobId + " for trigger " + to_string(triggerTime);
    }

    vector<long long> resolveCatchUp(const vector<long long>& missedTriggerTimes, const string& policy) {
        if (policy == "ALL") {
            return missedTriggerTimes;
        } else if (policy == "COALESCE") {
            if (missedTriggerTimes.empty()) return {};
            return {missedTriggerTimes.back()};
        } else if (policy == "SKIP") {
            return {};
        } else {
            throw invalid_argument("unknown policy: " + policy);
        }
    }

private:
    set<string> claimedTriggers;
};

string joinLongs(const vector<long long>& values) {
    string result = "[";
    for (size_t i = 0; i < values.size(); i++) {
        result += to_string(values[i]);
        if (i + 1 < values.size()) result += ", ";
    }
    result += "]";
    return result;
}

int main() {
    JobScheduler scheduler;

    // Two scheduler nodes race for the same trigger; only one should win.
    cout << scheduler.tryClaimAndExecute("node-1", "daily-report", 1000) << endl;
    cout << scheduler.tryClaimAndExecute("node-2", "daily-report", 1000) << endl;
    // A different trigger time for the same job has no conflict at all.
    cout << scheduler.tryClaimAndExecute("node-2", "daily-report", 2000) << endl;

    // The scheduler recovers after downtime; hourly-sync's schedule shows triggers
    // at 100, 200, 300, 400 with 200 and 300 missed while it was down, 400 not yet due.
    vector<long long> missed = {200, 300};
    cout << "ALL policy executes: " << joinLongs(scheduler.resolveCatchUp(missed, "ALL")) << endl;
    cout << "COALESCE policy executes: " << joinLongs(scheduler.resolveCatchUp(missed, "COALESCE")) << endl;
    cout << "SKIP policy executes: " << joinLongs(scheduler.resolveCatchUp(missed, "SKIP")) << endl;

    // A job with no missed triggers at all, coalescing an empty set stays empty.
    vector<long long> none = {};
    cout << "COALESCE policy with no missed triggers executes: " << joinLongs(scheduler.resolveCatchUp(none, "COALESCE")) << endl;

    return 0;
}

